tqsfrz2:
        move    x:(r7+$12),a
        tst     a
        bne     tqsfade
; SLEW: dS += (dT - dS) a; dA += (dS - dA) a  (a for 8 ticks; 48 bits)
        clr     b
        move    b,x:(r2+$10)
        move    x:(r2+$0d),a
        move    x:(r2+$0b),b
        move    x:(r2+$0c),b0
        sub     b,a
        move    a,x0
        move    #>$03ae53,y0
        mac     y0,x0,b
        move    b1,x:(r2+$0b)
        move    b0,x:(r2+$0c)
        move    x:(r2+$09),a
        move    x:(r2+$0a),a0
        sub     a,b
        move    b,x0
        mac     y0,x0,a
        move    a1,x:(r2+$09)
        move    a0,x:(r2+$0a)
        bra     tqsm0
tqsfade:
; FADE: a second head at the new time, crossfaded over 70 ms (cos / sin)
        move    x:(r2+$10),a
        tst     a
        bne     tqsfg
        move    x:(r2+$0d),a
        move    x:(r2+$09),x0
        sub     x0,a
        abs     a
        move    #>$0147ae,y0
        mpy     y0,x0,b
        add     #>$000800,b
        move    b,x1
        cmp     x1,a
        ble     tqsfh
        move    x:(r2+$0d),a
        move    a,x:(r2+$0e)
        move    #>$7fffff,a
        move    a,x:(r2+$10)
        clr     a
        move    a,x:(r2+$0f)
        move    a,x:(r3+$0a)
        move    #>$7fffff,a
        move    a,x:(r3+$08)
; the new head starts at its own target
        move    x:(r2+$0e),a
        move    x:(r2+$1d),x0
        add     x0,a
        bsr     >tqrel
        move    a1,x:(r3+$04)
        move    a0,x:(r3+$05)
        bra     tqsfg
tqsfh:
        move    x:(r2+$09),a
        move    a,x:(r2+$0b)
        clr     a
        move    a,x:(r2+$0c)
        bra     tqsm0
tqsfg:
        move    x:(r2+$0f),a
        cmp     #>$7fffff,a
        blt     tqsxf
; the fade ended last call: the new head is the head
        move    x:(r2+$0e),a
        move    a,x:(r2+$09)
        move    a,x:(r2+$0b)
        clr     a
        move    a,x:(r2+$0a)
        move    a,x:(r2+$0c)
        move    a,x:(r2+$10)
        move    a,x:(r3+$0a)
        move    a,x:(r3+$0b)
        move    a,x:(r3+$09)
        move    #>$7fffff,a
        move    a,x:(r3+$08)
        move    x:(r3+$04),a
        move    a,x:(r3+$00)
        move    x:(r3+$05),a
        move    a,x:(r3+$01)
        bra     tqsm0
tqsxf:
        add     #>$054eb3,a
        cmp     #>$7fffff,a
        blt     tqsxe
        move    #>$7fffff,a
tqsxe:
        move    a,x:(r2+$0f)
        move    a,x0
        move    #>$7fffff,a
        sub     x0,a
        bsr     >tqhsin
        asl     b
        move    x:(r3+$08),x0
        sub     x0,b
        asr     #$6,b,b
        move    b,x:(r3+$09)  ; to cos
        move    x:(r2+$0f),a
        bsr     >tqhsin
        asl     b
        move    x:(r3+$0a),x0
        sub     x0,b
        asr     #$6,b,b
        move    b,x:(r3+$0b)  ; to sin
; head B ramps to dB + wob
        move    x:(r2+$0e),a
        move    x:(r2+$1d),x0
        move    x:(r2+$1e),a0
        add     x0,a
        bsr     >tqrel
        move    x:(r3+$04),b
        move    x:(r3+$05),b0
        sub     b,a
        asr     #$6,a,a
        move    a1,x:(r3+$06)
        move    a0,x:(r3+$07)
        move    #>$000001,a
        bra     tqsmd
tqsm0:
        clr     a
tqsmd:
        move    a,x:(r3+$23)
; head A ramps to -(1 + max(8, dA + wob)) (whole.fraction, from the write pointer after it moves)
        move    x:(r2+$09),a
        move    x:(r2+$0a),a0
        move    x:(r2+$1d),b
        move    x:(r2+$1e),b0
        add     b,a
        bsr     >tqrel
        move    x:(r2+$12),b
        tst     b
        beq     tqsrmp
        move    a1,x:(r3+$00)
        move    a0,x:(r3+$01)
        clr     b
        move    b,x:(r2+$12)
tqsrmp:
        move    x:(r3+$00),b
        move    x:(r3+$01),b0
        sub     b,a
        asr     #$6,a,a
        move    a1,x:(r3+$02)
        move    a0,x:(r3+$03)
; feedback: k/2 = 1.05 regen / 2; gain-riding g = min(1, C / (k env)), env = the wet's peak envelope
        move    x:(r2+$1c),x0
        move    #>$7ec480,y0
        mpy     y0,x0,a
        move    x:(r3+$19),x0
        cmp     x0,a
        tlt     x0,a
        move    a,x:(r2+$1c)  ; env = max(peak, env x release)
        clr     b
        move    b,x:(r3+$19)
        move    a,x0
        move    x:(r7+$07),y0
        mpy     y0,x0,a  ; k env / 2
        move    #>$7fffff,b
        move    #>$026666,x0
        cmp     x0,a
        ble     tqsrg
        move    a,x1
        move    x0,a
        move    x1,x0
        bsr     >tqdiv
tqsrg:
        move    b,x0
        move    x:(r7+$07),y0
        mpy     y0,x0,a
        move    x:(r3+$1e),b
        sub     b,a
        asr     #$6,a,a
        move    a,x:(r3+$1f)  ; k g / 2: ramped tick by tick
; the HPF crossfades in / out over the same ticks (it switches without a click)
        move    x:(r7+$10),a
        tst     a
        beq     tqshpo
        move    #>$7fffff,a
tqshpo:
        move    x:(r3+$20),b
        sub     b,a
        asr     #$6,a,a
        move    a,x:(r3+$21)
        move    x:(r7+$10),a
        tst     a
        bne     tqshpx
        move    x:(r3+$20),a
        cmp     #>$004000,a
        bgt     tqshpx
        clr     a
        move    a,x:(r3+$20)
        move    a,x:(r3+$21)  ; off: exactly 0, the HPF skipped
tqshpx:
        move    x:(r3+$20),b
        tst     b
        bne     tqshpy
        move    x:(r3+$21),b
        move    b,x:(r3+$20)  ; from 0: the first step now (the tick skips the HPF while HPG is 0)
tqshpy:
        rts     
; ---- wow and flutter (for the next heads), on a call of their own ----
tqswob:
; wow
        move    x:(r2+$03),a
        sub     #>$0017c7,a
        move    a,x:(r2+$03)
        tst     a
        bgt     tqswt
        bsr     >tqrand
        sub     #>$400000,a
        asl     a
        move    a,x:(r2+$02)
        bsr     >tqrand
        move    #>$39999a,y0
        mpy     y0,x0,a
        add     #>$100000,a
        move    a,x:(r2+$03)
tqswt:
        move    x:(r2+$02),a
        move    x:(r2+$00),b
        sub     b,a
        move    a,x0
        move    #>$014708,y0
        mac     y0,x0,b
        move    b,x:(r2+$00)
        move    b,a
        move    x:(r2+$01),b
        sub     b,a
        move    a,x0
        move    #>$014708,y0
        mac     y0,x0,b
        move    b,x:(r2+$01)
; flutter: two sines, an amplitude that wanders
        move    x:(r2+$04),a
        move    x:(r2+$06),x0
        add     x0,a
        and     #>$7fffff,a
        move    a1,x:(r2+$04)
        move    x:(r2+$05),a
        move    x:(r2+$07),x0
        add     x0,a
        and     #>$7fffff,a
        move    a1,x:(r2+$05)
        bsr     >tqrand
        sub     #>$400000,a
        move    a,x0
        move    #>$056c14,y0
        mpy     y0,x0,a
        add     #>$400000,a  ; (0.5 + rand)/2, scaled as the plugin's per-sample draws average
        move    x:(r2+$08),b
        sub     b,a
        move    a,x0
        move    #>$06f07d,y0
        mac     y0,x0,b
        move    b,x:(r2+$08)
        move    x:(r2+$05),a
        bsr     >tqtsin
        move    b,x0
        move    #>$2ccccd,y0
        mpy     y0,x0,a
        move    a,x:(r7+$15)
        move    x:(r2+$04),a
        bsr     >tqtsin
        move    x:(r7+$15),a
        add     b,a
        move    a,x0  ; (s1 + 0.35 s2)/2
        move    x:(r2+$08),y0
        mpy     y0,x0,a
        move    a,x0  ; famp s / 4
        move    x:(r7+$0d),y0
        move    #>$200000,a
        move    #>$400000,y1
        mac     y1,y0,a
        move    a,y0  ; (1 + 2 wear)/4
        mpy     y0,x0,a
        move    a,x0
        move    #>$004f07,y0
        mpy     y0,x0,b  ; 4 flutter, A-units
        move    x:(r7+$0d),y0
        move    #>$200000,a
        move    #>$333333,y1
        mac     y1,y0,a
        move    a,x0  ; (1 + 1.6 wear)/4
        move    x:(r2+$01),y0
        mpy     y0,x0,a
        move    a,x0
        move    #>$05c9c3,y0
        mac     y0,x0,b
        move    b,x0  ; 4 (wow + flutter), A-units
        move    x:(r7+$08),y0  ; W/4
        mpy     y0,x0,b  ; wob, A-units (48 bits)
        move    b1,x:(r2+$1d)
        move    b0,x:(r2+$1e)
        rts     
; ---- the damage, on another call ----
tqsdmg:
; damage at the write head: record gain 1.148 (1 - 0.8 d)(1 - 0.18 wear), ramped over the call
        move    x:(r2+$1b),a
        move    x:(r2+$14),x0
        sub     x0,a
        bsr     >tqdmg
        move    b,x0
        move    x:(r7+$0b),y0
        mpy     y0,x0,a
        move    a,x0
        move    #>$7fffff,a
        move    #>$666666,y0
        mac     -y0,x0,a
        move    a,x0
        move    x:(r7+$0d),y0
        move    #>$7fffff,a
        move    #>$170a3d,y1
        mac     -y1,y0,a
        move    a,y0
        mpy     y0,x0,a
        move    a,x0
        move    #>$497b7c,y0
        mpy     y0,x0,a
        move    x:(r3+$1a),x0
        sub     x0,a
        asr     #$6,a,a
        move    a,x:(r3+$1b)
; damage at the read head (w - 1 - dA; frozen: the loop position)
        move    x:(r2+$11),a
        tst     a
        beq     tqsrp
        move    x:(r3+$26),a
        bra     tqsrq
tqsrp:
        move    x:(r2+$09),a
        add     #>$100,a
        asr     #$9,a,a
        neg     a
        sub     #>$1,a
tqsrq:
        move    x:(r2+$1b),x0
        add     x0,a
        move    x:(r2+$14),x0
        sub     x0,a
        bge     tqsrw
        move    x:(r2+$15),x0
        add     x0,a
tqsrw:
        bsr     >tqdmg
        move    b,x0
        move    x:(r7+$0b),y0
        mpy     y0,x0,a
        move    a,x:(r7+$16)  ; dr
        move    a,x0
        move    #>$7fffff,a
        move    #>$333333,y0
        mac     -y0,x0,a
        move    a,x:(r3+$1d)
; gap loss: fc = 15 kHz (1 - 0.8 wear)(1 - 0.55 dr); a = wc/(1 + wc)
        move    #>$7fffff,a
        move    #>$466666,y0
        mac     -y0,x0,a
        move    a,x1
        move    x:(r7+$0d),y0
        move    #>$7fffff,a
        move    #>$666666,x0
        mac     -y0,x0,a
        move    a,y0
        mpy     x1,y0,a
        move    a,x0
        move    #>$44636f,y0
        mpy     y0,x0,a  ; wc/8
        move    a,y1
        add     #>$100000,a
        move    a,x0
        move    y1,a
        bsr     >tqdiv
        move    b,x:(r3+$1c)
; crackle: wear > 0.25, chance 0.00003 w^2 (1 + 8 dr) a 48 kHz sample
        move    x:(r7+$0d),a
        cmp     #>$200000,a
        ble     tqsnc
        move    a,x0
        mpy     x0,x0,a
        move    a,x1
        move    x:(r7+$16),x0
        move    #>$0e38e4,a
        move    #>$71c71c,y0
        mac     y0,x0,a
        move    a,y0
        mpy     x1,y0,a
        move    a,x0
        move    #>$04d09d,y0
        mpy     y0,x0,a
        move    a,x:(r7+$15)
        bsr     >tqrand
        move    x:(r7+$15),x1
        cmp     x1,a
        bge     tqsnc
        bsr     >tqrand
        sub     #>$400000,a
        move    a,x0
        move    x:(r7+$0d),y0
        mpy     y0,x0,a
        move    a,x0
        move    x:(r7+$1a),y0
        mpy     y0,x0,a
        move    a,x0
        move    #>$0147ae,y0
        mpy     y0,x0,a
        move    a,x:(r3+$14)
tqsnc:
; flakes: (0.01 + 0.12 age^2) a second on the plugin's 165-block tape; here x nb/165
        move    x:(r7+$0c),a
        cmp     #>$0020c5,a
        ble     tqsnk
        move    a,x0
        mpy     x0,x0,a
        move    a,x0
        move    #>$762762,y0
        move    #>$09d89e,a
        mac     y0,x0,a
        move    a,x0
        move    x:(r2+$1a),y0
        mpy     y0,x0,a
        asr     #$6,a,a
        move    a,x:(r7+$15)
        bsr     >tqrand
        move    x:(r7+$15),x1
        cmp     x1,a
        bge     tqsnk
        bsr     >tqflk
tqsnk:
        rts     
; ======== a side, one tape sample (r2/r3 = the side, n0 = 0 left / 1 right, m1 = its ring) ========
tqtick:
        move    x:(r3+$23),b
        cmp     #>$000002,b
        beq     tqtfz  ; frozen: nothing is recorded
; decimate: d = (A0(x[2n]) + A1(x[2n-1]))/2 at 1/8
        move    x:(r0+n0),a
        asr     #$3,a,a
        move    a,x0
        move    x:(r3+$2f),a
        move    #>$1618f2,y0
        mac     y0,x0,a
        move    x:(r3+$30),x1
        mac     -x1,y0,a
        move    x0,x:(r3+$2f)
        move    a,x:(r3+$30)
        move    a,x0
        move    x1,a
        move    #>$6bf6ae,y0
        mac     y0,x0,a
        move    x:(r3+$31),x1
        mac     -x1,y0,a
        move    a,x:(r3+$31)
        move    a,x0
        move    a,x:(r3+$25)
        move    x:(r3+$2d),x0
        move    x:(r3+$32),a
        move    #>$428e85,y0
        mac     y0,x0,a
        move    x:(r3+$33),x1
        mac     -x1,y0,a
        move    x0,x:(r3+$32)
        move    a,x:(r3+$33)
        move    a,x0
        move    x:(r3+$25),b
        add     b,a
        asr     a  ; d
; record head: u = d + fb; pre-emphasis; x 1.148 (1 - 0.8 d)(1 - 0.18 wear); no saturation
        move    x:(r3+$0c),x0
        add     x0,a
        move    a,x1  ; u
        move    x:(r3+$0d),b
        sub     b,a
        move    a,x0
        move    #>$3f6787,y0
        mac     y0,x0,b
        move    b,x:(r3+$0d)
        move    x1,a
        move    #>$26c1e2,y0
        mac     y0,x0,a  ; e = u + 0.6 (u - pre'), pre' = pre + a (u - pre)
        move    a,x0
        move    x:(r3+$1a),b
        move    x:(r3+$1b),y0
        add     y0,b
        move    b,x:(r3+$1a)
        move    b,y0
        mpy     y0,x0,a
        asl     a
        move    x:(r2+$13),b
        tst     b
        bne     tqtwx
        move    a,y:(r4)+
        bra     tqtwd
tqtwx:
        move    a,x:(r5)+
tqtwd:
; playback head A
        move    x:(r3+$00),a
        move    x:(r3+$01),a0
        move    x:(r3+$02),b
        move    x:(r3+$03),b0
        add     b,a
        move    a1,x:(r3+$00)
        move    a0,x:(r3+$01)
        bsr     >tqherm
        move    x:(r3+$23),b
        tst     b
        beq     tqtout
; fade: head B, the gains (cos / sin) ramped
        move    x:(r3+$08),b
        move    x:(r3+$09),x0
        add     x0,b
        move    b,x:(r3+$08)
        move    b,x0
        move    a,y0
        mpy     y0,x0,a
        move    a,x:(r3+$22)
        move    x:(r3+$04),a
        move    x:(r3+$05),a0
        move    x:(r3+$06),b
        move    x:(r3+$07),b0
        add     b,a
        move    a1,x:(r3+$04)
        move    a0,x:(r3+$05)
        bsr     >tqlrd  ; the incoming head reads linearly (70 ms; it saves 26 instructions while fading)
        move    x:(r3+$0a),b
        move    x:(r3+$0b),x0
        add     x0,b
        move    b,x:(r3+$0a)
        move    b,x0
        move    a,y0
        mpy     y0,x0,a
        move    x:(r3+$22),b
        add     b,a
        bra     tqtout
tqtfz:
; frozen: Q steps round the loop; read at Q - wob/2; the splice crossfades the last X samples
        move    x:(r3+$26),a
        add     #>$1,a
        move    x:(r3+$27),x0
        cmp     x0,a
        blt     tqtqw
        move    x:(r3+$29),x0
        sub     x0,a
tqtqw:
        move    a1,x:(r3+$26)
        bsr     >tqdisd
        move    x:(r3+$04),a
        move    x:(r3+$05),a0
        move    x:(r3+$06),b
        move    x:(r3+$07),b0
        add     b,a
        move    a1,x:(r3+$04)
        move    a0,x:(r3+$05)
        move    a,b
        clr     a
        move    x:(r3+$26),a1
        sub     #>$1,a
        sub     b,a
        move    a1,x:(r3+$00)
        move    a0,x:(r3+$01)
        bsr     >tqherm
        move    x:(r3+$26),b
        move    x:(r3+$28),x0
        cmp     x0,b
        ble     tqtout
        move    a,x:(r3+$2e)  ; (O1 as scratch: set again below)
        sub     x0,b
        move    b1,x0
        move    x:(r3+$2a),y0
        mpy     y0,x0,b
        asl     #$17,b,b
        move    b1,x:(r3+$22)  ; t = (Q - QSPL)/X
        move    x:(r3+$00),a
        move    x:(r3+$01),a0
        move    x:(r3+$29),x0
        sub     x0,a
        bsr     >tqlrd  ; the spliced-in read is linear (it fades in from 0)
        move    x:(r3+$2e),b
        sub     b,a
        move    a,x0
        move    x:(r3+$22),y0
        mac     y0,x0,b
        move    b,a  ; out (1 - t) + t spliced
tqtout:
; gap loss (two one-poles), head bump, de-emphasis, dropout
        move    x:(r3+$0e),b
        sub     b,a
        move    a,x0
        move    x:(r3+$1c),y0
        mac     y0,x0,b
        move    b,x:(r3+$0e)
        move    b,a
        move    x:(r3+$0f),b
        sub     b,a
        move    a,x0
        mac     y0,x0,b
        move    b,x:(r3+$0f)
        move    b,x0
        move    x0,x1  ; head bump: Chamberlin SVF (lp += f bp; hp = x - lp - q bp; bp += f hp)
        move    x:(r3+$11),a
        move    x:(r3+$10),x0
        move    #>$037704,y0
        mac     y0,x0,a
        move    a,x:(r3+$11)
        move    x1,b
        sub     a,b
        move    #>$7b28cd,y1
        mac     -x0,y1,b
        move    b,y1
        move    x0,a
        mac     y1,y0,a
        move    a,x:(r3+$10)
        move    a,x0
        move    x1,a
        move    #>$291388,y0
        mac     y0,x0,a  ; x + (A^2 - 1) q bp
        move    a,x1
        move    x:(r3+$12),b
        sub     b,a
        move    a,x0
        move    #>$3f6787,y0
        mac     y0,x0,b
        move    b,x:(r3+$12)
        move    x1,a
        move    #>$18392d,y0
        mac     -y0,x0,a  ; y - 0.375 (y - dem')
        move    a,x0
        move    x:(r3+$1d),y0
        mpy     y0,x0,a
        move    a,x:(r3+$25)
; hiss: white > 11 kHz lowpass - its 900 Hz lowpass, x (0.0018 + 0.008 wear) x the fade x HISS
        move    x:(r7+$14),x0
        move    #>$0343fd,y0
        mpy     y0,x0,a
        asr     a
        move    a0,x0
        move    x0,a
        add     #>$269ec3,a
        move    a1,x:(r7+$14)  ; the LCG inline: a = white, -1..1
        move    a,x1
        move    x:(r3+$13),b
        sub     b,a
        move    a,x0
        move    #>$1cf47f,y0
        mac     y0,x0,b
        move    b,x:(r3+$13)
